INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(17063599, 'Heavenly Zephyr - Miradora', '风之天翼 米勒德拉', '風の天翼ミラドーラ', 'Effect Monster', 'Dragon', 'WIND', 7, 2000, 2600, '这个卡名的①②的效果1回合各能使用1次，那些发动和效果不会被无效化。 ①：对方从额外卡组把攻击力2000以上的怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合，以从额外卡组特殊召唤的对方场上1只表侧表示怪兽为对象才能发动。这只怪兽表侧表示存在期间，作为对象的怪兽不能把效果发动。'),
(49121795, 'Heavy Armored Train Ironwolf', '重装甲列车铁狼', '重装甲列車アイアン・ヴォルフ', 'XYZ Monster', 'Machine', 'EARTH', 4, 2200, 2200, '机械族4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只机械族怪兽为对象才能发动。这个回合，那只怪兽以外的怪兽不能攻击，那只怪兽可以直接攻击。 ②：这张卡被对方破坏送去墓地的场合才能发动。从卡组把1只机械族·4星怪兽加入手卡。'),
(14357527, 'Heavy Beetrooper Mighty Neptune', '重骑甲虫 雄威尼普顿', '重騎甲虫マイティ・ネプチューン', 'Effect Monster', 'Insect', 'EARTH', 8, 3000, 3000, '这张卡不能通常召唤。让除外的3只自己的昆虫族怪兽回到卡组的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：结束阶段，以这张卡以外的自己场上1只昆虫族怪兽为对象才能发动。那只怪兽的攻击力上升1000。 ②：自己·对方的主要阶段，场上的这张卡被对方的效果所破坏的场合或者所除外的场合才能发动。这张卡特殊召唤。'),
(50123605, 'Heavy Cavalry of the Indestructible Insects', '无死虫团的重骑兵', '無死虫団の重騎兵', 'Fusion Monster', 'Insect', 'EARTH', 7, 2500, 1800, '5星以上的昆虫族怪兽＋昆虫族怪兽 这个卡名的②的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不会被对方的效果破坏。 ②：自己·对方回合，自己场上的表侧表示怪兽只有昆虫族怪兽的场合，以包含自己场上的昆虫族怪兽的场上2只怪兽为对象才能发动。那些怪兽除外。'),
(34721681, 'Heavy Forward', '超重机回送', '超重機回送', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「无限起动」怪兽加入手卡。 ②：1回合1次，可以以自己场上1只机械族超量怪兽为对象，从以下效果选择1个发动。 ●那只怪兽的表示形式变更。 ●把这张卡在那只怪兽下面重叠作为超量素材。'),
(13647631, 'Heavy Freight Train Derricrane', '重机货列车 起重吊臂', '重機貨列車デリックレーン', 'Effect Monster', 'Machine', 'EARTH', 10, 2800, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有机械族·地属性怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的原本的攻击力·守备力变成一半。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除送去墓地的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(20071842, 'Heavy Interlock', '重型扳机', 'ヘヴィ・トリガー', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「装弹枪管暴动龙」的降临必需。 ①：等级合计直到8以上为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把自己的手卡·场上的「弹丸」怪兽破坏，从手卡把「装弹枪管暴动龙」仪式召唤。这个效果特殊召唤的怪兽不会被和从额外卡组特殊召唤的怪兽的战斗破坏，不受从额外卡组特殊召唤的怪兽发动的效果影响。'),
(45116390, 'Heavy Knight Babel Decker', NULL, NULL, 'Effect Monster', 'Machine', 'EARTH', 10, 500, 3000, NULL),
(34761062, 'Heavy Knight of the Flame', '业火之重骑士', '業火の重騎士', 'Gemini Monster', 'Zombie', 'FIRE', 4, 1800, 200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡向特殊召唤的怪兽攻击的伤害步骤开始时才能发动。那只怪兽除外。'),
(39890958, 'Heavy Mech Support Armor', '强化支援机械・重装铠甲', '強化支援メカ・ヘビーアーマー', 'Union Effect Monster', 'Machine', 'LIGHT', 3, 500, 500, '①：这张卡召唤成功的场合，以自己墓地1只同盟怪兽为对象才能发动。那只怪兽特殊召唤。 ②：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ③：装备怪兽不会成为对方的效果的对象。'),
(23265594, 'Heavy Mech Support Platform', '强化支援机械·重装武器', '強化支援メカ・ヘビーウェポン', 'Union Effect Monster', 'Machine', 'DARK', 3, 500, 500, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽的攻击力·守备力上升500。'),
(3113667, 'Heavy Metal Raiders', '钢铁袭击者', '鋼鉄の襲撃者', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己的机械族·暗属性怪兽在1回合各有1次不会被战斗破坏，那次战斗让自己受到战斗伤害的场合，攻击力上升那个数值。 ②：1回合1次，自己场上的原本的种族·属性是机械族·暗属性的怪兽用战斗或者自身的效果破坏场上的卡的场合才能发动。从手卡把1只机械族·暗属性怪兽特殊召唤。'),
(300103001, 'Heavy Metal Raiders (Skill Card)', NULL, NULL, 'Skill Card', 'Keith', NULL, NULL, NULL, NULL, NULL),
(58570206, 'Heavy Polymerization', '多层融合', '多層融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤（融合素材怪兽必须是3只以上）。对方场上有怪兽存在的场合，也能把最多有那个数量的自己的额外卡组的怪兽除外作为融合素材。那个场合，融合召唤时自己失去那个攻击力合计数值的基本分。'),
(52417194, 'Heavy Slump', '大暴落', '大暴落', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的手卡在8张以上时发动。对方把手卡加入卡组洗切，之后抽2张卡。'),
(19613556, 'Heavy Storm', '大岚', '大嵐', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的魔法·陷阱卡全部破坏。'),
(23924608, 'Heavy Storm Duster', '沙尘大岚', '砂塵の大嵐', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：以场上最多2张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(61728808, 'Heavymetalfoes Amalgam', '刚炼装勇士·汞齐混融者', 'ヘビーメタルフォーゼ・アマルガム', 'Link Monster', 'Psychic', 'FIRE', NULL, 2000, NULL, '「炼装」怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡被效果从怪兽区域送去墓地的场合，可以从以下效果选择1个发动。 ●以自己场上1只「炼装」怪兽为对象才能发动。这张卡当作攻击力上升1000的装备卡使用给那只怪兽装备。 ●以自己场上1张「炼装」卡为对象才能发动。那张卡破坏，这张卡特殊召唤。'),
(24094258, 'Heavymetalfoes Electrumite', '强炼装・银金', 'ヘビーメタルフォーゼ・エレクトラム', 'Link Monster', 'Psychic', 'FIRE', NULL, 1800, NULL, '灵摆怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1只灵摆怪兽表侧加入额外卡组。 ②：1回合1次，以自己场上1张其他的表侧表示卡为对象才能发动。那张卡破坏。那之后，从自己的额外卡组（表侧）把1只灵摆怪兽加入手卡。 ③：自己的灵摆区域的卡从场上离开的场合发动。自己抽1张。'),
(90365482, 'Hebo, Lord of the River', '河伯', '河伯', 'Spirit Monster', 'Aqua', 'WATER', 4, 1800, 600, '这张卡不能特殊召唤。 ①：这张卡召唤·反转的场合，以场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽变成当作灵魂怪兽使用，结束阶段回到持有者手卡。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(20415050, 'Hecahands', '神之百臂无形手', '神の見えざる手', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。这张卡也能把自己场上1张其他卡送去墓地来发动。 ①：从卡组把1只「不可见之手」怪兽加入手卡。把卡送去墓地来把这张卡发动的场合，可以再从卡组把「神的不可见之手」以外的1张「不可见之手」魔法·陷阱卡在自己场上盖放。 ②：把墓地的这张卡除外才能发动。对方抽1张。那之后，对方选自身1张手卡丢弃。'),
(21637502, 'Hecahands Breus', '百臂无形手 布瑞撕', '見えざる手ブレアス', 'Effect Monster', 'Illusion', 'DARK', 7, 2800, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：抽卡阶段以外让对方手卡有卡加入的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。把对方手卡随机1张确认。那是怪兽的场合，可以把那只怪兽在自己场上特殊召唤。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(31411835, 'Hecahands Dandalos', NULL, NULL, 'Fusion Monster', 'Illusion', 'DARK', 7, 2900, 3000, NULL),
(95132593, 'Hecahands Gaigas', '百臂无形手 盖伽撕', '見えざる手ガイガス', 'Effect Monster', 'Illusion', 'DARK', 7, 1200, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：抽卡阶段以外让对方手卡有卡加入的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从对方卡组上面把3张卡翻开。可以从那之中选1只怪兽在自己场上特殊召唤。剩余回到卡组。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(68144894, 'Hecahands Godos', '百臂无形手 格多撕', '見えざる手ゴッドス', 'Effect Monster', 'Illusion', 'DARK', 7, 2300, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：抽卡阶段以外让对方手卡有卡加入的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：对方主要阶段，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(95365081, 'Hecahands Ibtel', '百臂无形手 伊卜揶尔', '見えざる手イブエル', 'Effect Monster', 'Illusion', 'LIGHT', 6, 1600, 2100, '这个卡名的①③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。这张卡回到卡组。那之后，从卡组把「不可见之手 诱天手」以外的1只「不可见之手」怪兽守备表示特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：这张卡被送去墓地的场合，以「不可见之手 诱天手」以外的自己墓地1只「不可见之手」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(67021206, 'Hecahands Jauzah', '百臂无形神 迦乌撒', '見えざる神ジャウザー', 'Fusion Monster', 'Illusion', 'LIGHT', 8, 2400, 2500, '「不可见之手」怪兽＋幻想魔族怪兽 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上1只幻想魔族怪兽和1只原本持有者是对方的表侧表示怪兽解放的场合可以特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从自己的卡组·墓地把1张「不可见之手」卡加入手卡。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(18321034, 'Hecahands Makibel', NULL, NULL, 'Effect Monster', 'Illusion', 'LIGHT', 6, 1850, 1850, NULL),
(57809669, 'Hecahands Tartaros', '百臂无形幽狱 塔尔塔洛撕', '見えざる幽獄', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己场上有「不可见之手」怪兽存在的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到手卡。 ●自己的场上·墓地的怪兽作为融合素材除外，把1只「不可见之手」融合怪兽融合召唤。把原本持有者是对方的自己场上的表侧表示怪兽作为融合素材的场合，可以当作「不可见之手」怪兽使用。'),
(94410955, 'Hecahands Xeno', '百臂无形神 慑挪', '見えざる神ゼノ', 'Fusion Monster', 'Illusion', 'DARK', 9, 3400, 3500, '「不可见之手」怪兽×3 这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。把对方的额外卡组的里侧的卡随机2张确认。可以从那之中选1张在自己场上特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：融合召唤的这张卡被对方的效果破坏的场合才能发动。选对方场上的怪兽任意数量，得到那些控制权。'),
(32759190, 'Hecahands Yadel', '百臂无形手 雅多揶尔', '見えざる手ヤドエル', 'Effect Monster', 'Illusion', 'LIGHT', 6, 2100, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。这张卡回到卡组。那之后，从卡组把1张「不可见之手」魔法·陷阱卡加入手卡。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：这张卡被送去墓地的场合，以自己墓地1张「不可见之手」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(74968065, 'Hecatrice', '赫卡忒利斯', 'ヘカテリス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 1100, '①：自己主要阶段把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「神之居城-瓦尔哈拉」加入手卡。'),
(59042331, 'Hedge Guard', '守卫竹篱', 'ガード・ヘッジ', 'Effect Monster', 'Plant', 'EARTH', 3, NULL, 2100, '战斗伤害计算时，把这张卡从手卡送去墓地发动。自己场上存在的怪兽不会被那次战斗破坏，攻击力直到这个回合的结束阶段时变成一半数值。'),
(75660578, 'Hela, Generaider Boss of Doom', '死之创王 赫尔', '死の王 ヘル', 'Effect Monster', 'Zombie', 'DARK', 9, 800, 2800, '这个卡名的②的效果1回合只能使用1次。 ①：「死界王战 赫尔女王」在自己场上只能有1只表侧表示存在。 ②：把自己场上1只「王战」怪兽或者不死族怪兽解放，以和那只怪兽卡名不同的自己墓地1只「王战」怪兽或者不死族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果在对方回合也能发动。'),
(54493213, 'Helios - The Primordial Sun', '原始太阳 赫利俄斯', '原始太陽ヘリオス', 'Effect Monster', 'Pyro', 'LIGHT', 4, -1, -1, '①：这张卡的攻击力·守备力变成除外状态的怪兽数量×100。'),
(80887952, 'Helios Duo Megistus', '双子太阳 赫利俄斯', 'ヘリオス・デュオ・メギストス', 'Effect Monster', 'Pyro', 'LIGHT', 6, -1, -1, '这张卡可以用自己场上的1只「原始太阳 赫利俄斯」作为祭品特殊召唤。这张卡的攻击力·守备力为从游戏中除外的怪兽卡数量×200的数值。这张卡被战斗破坏送去墓地的场合，结束阶段时攻击力·守备力上升300并特殊召唤。'),
(17286057, 'Helios Trice Megistus', '三子太阳 赫利俄斯', 'ヘリオス・トリス・メギストス', 'Effect Monster', 'Pyro', 'LIGHT', 8, -1, -1, '这张卡可以用自己场上的1只「双子太阳 赫利俄斯」作为祭品特殊召唤。这张卡的攻击力·守备力为从游戏中除外的怪兽卡数量×300的数值。这张卡被战斗破坏送去墓地的场合，结束阶段时攻击力·守备力上升500并特殊召唤。对方场上有怪兽存在的场合，只有1次可以继续进行攻击。'),
(51043053, 'Heliosphere Dragon', '防霸龙 日球层龙', '防覇龍ヘリオスフィア', 'Effect Monster', 'Dragon', 'LIGHT', 4, NULL, 1900, '对方手卡是4张以下而自己场上的怪兽只有这张卡的场合，对方不能攻击宣言。此外，1回合1次，自己场上有龙族·8星怪兽存在的场合才能发动。这张卡的等级直到结束阶段时变成8星。'),
(60880471, 'Hellebore the Rikka Fairy', '六花精圣诞玫瑰', '六花精ヘレボラス', 'Effect Monster', 'Plant', 'WATER', 8, 2600, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「六花」怪兽存在，自己场上的怪兽为对象的怪兽的效果由对方发动时，把手卡·场上的这张卡解放才能发动。那个效果无效。 ②：这张卡在墓地存在的场合，把自己场上1只植物族怪兽解放才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(67466547, 'Helmer, Helmsman Fur Hire', '空牙团的舵手 赫玛', '空牙団の舵手 ヘルマー', 'Effect Monster', 'Aqua', 'WATER', 3, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的舵手 赫耳玛」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合，从手卡丢弃1张「空牙团」卡才能发动。自己从卡组抽1张。'),
(47025270, 'Helping Robo for Combat', '白兵战型援助机器人', '白兵戦型お手伝いロボ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1600, NULL, '这张卡每次战斗破坏对方怪兽，自己抽1张卡，之后从手卡选择1张卡放回卡组最下面。'),
(76052811, 'Helpoemer', '地狱诗人', '地獄詩人ヘルポエマー', 'Effect Monster', 'Fiend', 'DARK', 5, 2000, 1400, '这张卡不能作从墓地的特殊召唤。 ①：被战斗破坏的这张卡在墓地存在的场合，对方战斗阶段结束时发动。这张卡在墓地存在的场合，对方手卡随机选1张丢弃。'),
(92079625, 'Helshaddoll Hollow', '狱影依的炎核 虚炼', '影依の炎核 ヴォイド', 'Flip Effect Monster', 'Fiend', 'FIRE', 9, 2900, 2900, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合，以对方场上1只表侧表示怪兽为对象才能发动。属性和那只怪兽相同的1只「影依」怪兽从额外卡组送去墓地，作为对象的怪兽除外。 ②：这张卡被效果送去墓地的场合才能发动。把场上的怪兽的原本属性种类数量的卡从自己卡组上面送去墓地。'),
(8963089, 'Heosvarog the Mechanical Dawn', '黎铭机 厄俄史瓦罗格', '黎銘機ヘオスヴァローグ', 'Fusion Monster', 'Machine', 'LIGHT', 7, NULL, 2800, '机械族·光属性怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。下个回合的准备阶段，把持有融合召唤效果的1张卡从自己墓地加入手卡。 ②：对方把魔法·陷阱卡的效果发动时，把自己场上1只表侧表示的机械族·光属性怪兽或者自己墓地2只机械族·光属性怪兽除外才能发动。那个发动无效。'),
(66337215, 'Herald of Creation', '创世的预言者', '創世の預言者', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 600, '①：1回合1次，丢弃1张手卡，以自己墓地1只7星以上的怪兽为对象才能发动。那只怪兽加入手卡。'),
(21074344, 'Herald of Green Light', '绿光之宣告者', '緑光の宣告者', 'Effect Monster', 'Fairy', 'LIGHT', 2, 300, 500, '①：对方把魔法卡发动时，从手卡把这张卡和1只天使族怪兽送去墓地才能发动。那个发动无效并破坏。'),
(46935289, 'Herald of Mirage Lights', '虚光之宣告者', '虚光の宣告者', 'Link Monster', 'Fairy', 'LIGHT', NULL, 600, NULL, '衍生物以外的相同种族·属性的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：魔法·陷阱卡的效果发动时，从手卡把1只天使族怪兽送去墓地才能发动。那个发动无效并破坏。 ②：这张卡被对方送去墓地的场合才能发动。从自己墓地的仪式怪兽以及仪式魔法卡之中选合计最多2张加入手卡（同名卡最多1张）。'),
(17266660, 'Herald of Orange Light', '朱光之宣告者', '朱光の宣告者', 'Tuner Monster', 'Fairy', 'LIGHT', 2, 300, 500, '①：对方把怪兽的效果发动时，从手卡把这张卡和1只天使族怪兽送去墓地才能发动。那个发动无效并破坏。'),
(44665365, 'Herald of Perfection', '神光之宣告者', '神光の宣告者', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 6, 1800, 2800, '「宣告者的预言」降临。 ①：对方把怪兽的效果·魔法·陷阱卡发动时，从手卡把1只天使族怪兽送去墓地才能发动。那个发动无效并破坏。'),
(1249315, 'Herald of Pure Light', '圣光之宣告者', '聖光の宣告者', 'XYZ Monster', 'Fairy', 'LIGHT', 2, 600, 1000, '2星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以自己墓地1只怪兽为对象才能发动。那只怪兽加入手卡。那之后，选1张手卡回到卡组。'),
(94689635, 'Herald of Purple Light', '紫光之宣告者', '紫光の宣告者', 'Effect Monster', 'Fairy', 'LIGHT', 2, 300, 500, '①：对方把陷阱卡发动时，从手卡把这张卡和1只天使族怪兽送去墓地才能发动。那个发动无效并破坏。'),
(94016752, 'Herald of the Abyss', '深渊之宣告者', '深淵の宣告者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上有表侧表示怪兽存在的场合，支付1500基本分，宣言种族和属性各1个才能发动。宣言的种族·属性的怪兽在对方场上表侧表示存在的场合，对方必须把那之内的1只送去墓地。这个回合，对方不能把那只怪兽以及那些同名怪兽的怪兽效果发动。'),
(79606837, 'Herald of the Arc Light', '虹光之宣告者', '虹光の宣告者', 'Synchro Monster', 'Fairy', 'LIGHT', 4, 600, 1000, '调整＋调整以外的怪兽1只以上 ①：只要这张卡在怪兽区域存在，从双方的手卡·卡组送去墓地的怪兽不去墓地而除外。 ②：怪兽的效果·魔法·陷阱卡发动时，把这张卡解放才能发动。那个发动无效并破坏。 ③：这张卡被送去墓地的场合才能发动。从卡组把1只仪式怪兽或者1张仪式魔法卡加入手卡。'),
(48546368, 'Herald of Ultimateness', '崇光之宣告者', '崇光なる宣告者', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 12, 2000, 3000, '「宣告者的神托」降临。这张卡不用仪式召唤不能特殊召唤。 ①：可以从手卡把1只天使族怪兽送去墓地把以下效果发动。 ●对方把怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(60316373, 'Heraldic Beast Aberconway', '纹章兽 亚伯康威', '紋章獣アバコーンウェイ', 'Effect Monster', 'Dragon', 'WIND', 4, 1800, 900, '这张卡在墓地存在的场合，把这张卡以外的自己墓地1只「纹章兽 阿伯康韦龙」从游戏中除外才能发动。选择自己墓地1只名字带有「纹章兽」的怪兽加入手卡。「纹章兽 阿伯康韦龙」的效果1回合只能使用1次。'),
(87255382, 'Heraldic Beast Amphisbaena', '纹章兽 双头蛇', '紋章獣アンフィスバエナ', 'Effect Monster', 'Dragon', 'WIND', 4, 1700, 1100, '自己的主要阶段时，从手卡把这张卡以外的1只名字带有「纹章兽」的怪兽丢弃才能发动。这张卡从手卡特殊召唤。此外，1回合1次，从手卡丢弃1只名字带有「纹章兽」的怪兽才能发动。这张卡的攻击力直到结束阶段时上升800。'),
(56921677, 'Heraldic Beast Basilisk', '纹章兽 巴西利斯克', '紋章獣バシリスク', 'Effect Monster', 'Beast', 'EARTH', 4, 1000, 1400, '这张卡和对方怪兽进行战斗的伤害计算后，那只对方怪兽破坏。'),
(96704018, 'Heraldic Beast Berners Falcon', '纹章兽 伯纳斯猎鹰', '紋章獣ベルナーズ・ファルコン', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1000, 1600, '这张卡召唤·反转召唤·特殊召唤成功时才能发动。自己场上的全部5星以上的怪兽的等级变成4星。'),
(82315772, 'Heraldic Beast Eale', '纹章兽 野迩', '紋章獣エアレー', 'Effect Monster', 'Beast', 'EARTH', 4, 1000, 1800, '自己场上有名字带有「纹章兽」的怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。'),
(60268386, 'Heraldic Beast Gryphon', '纹章兽 狮鹫', '紋章獣グリフォン', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把「纹章兽 狮鹫」以外的1只「纹章兽」怪兽送去墓地才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非以只用原本卡名包含「纹章兽」或「No.」的怪兽为素材的超量召唤则不能从额外卡组把怪兽特殊召唤。 ②：以怪兽3只以上为素材的「No.」超量怪兽超量召唤的场合，这张卡可以作为2只数量的超量素材。'),
(82293134, 'Heraldic Beast Leo', '纹章兽 雄狮', '紋章獣レオ', 'Effect Monster', 'Beast', 'EARTH', 4, 2000, 1000, '这张卡召唤的回合的结束阶段时，这张卡破坏。此外，这张卡被送去墓地时，从卡组把「纹章兽 狮子」以外的1只名字带有「纹章兽」的怪兽加入手卡。「纹章兽 狮子」的这个效果1回合只能使用1次。'),
(97662494, 'Heraldic Beast Stad Whale', '纹章兽 斯塔德鲸', '紋章獣スタット・ホエール', 'Effect Monster', 'Fish', 'WATER', 4, 900, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，丢弃1张手卡才能发动。从卡组把2张「纹章」魔法·陷阱卡加入手卡。 ②：把墓地的这张卡除外，以自己墓地2只同名「纹章兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己若非以只用原本卡名包含「纹章兽」或「No.」的怪兽为素材的超量召唤则不能从额外卡组把怪兽特殊召唤。'),
(19310321, 'Heraldic Beast Twin-Headed Eagle', '纹章兽 双头鹰', '紋章獣ツインヘッド・イーグル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1200, 1400, '把墓地的这张卡从游戏中除外，选择自己场上1只没有超量素材的超量怪兽和自己墓地2只名字带有「纹章兽」的怪兽才能发动。选择的墓地的怪兽在选择的超量怪兽下面重叠作为超量素材。「纹章兽 双头鹰」的效果1回合只能使用1次。'),
(45705025, 'Heraldic Beast Unicorn', '纹章兽 独角兽', '紋章獣ユニコーン', 'Effect Monster', 'Beast', 'LIGHT', 4, 1100, 1600, '把墓地的这张卡从游戏中除外，选择自己墓地1只念动力族超量怪兽才能发动。选择的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「纹章兽 独角兽」的效果1回合只能使用1次。'),
(17536995, 'Heraldry Change', '纹章变换', '紋章変換', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。从手卡把1只名字带有「纹章兽」的怪兽特殊召唤，战斗阶段结束。'),
(84220251, 'Heraldry Reborn', '苏生徽章', '蘇生紋章', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地1只名字带有「纹章兽」的怪兽才能发动。选择的怪兽特殊召唤。'),
(37241623, 'Heraldry Record', '纹章的记录', '紋章の記録', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方场上的超量怪兽把那超量素材取除来让效果发动时才能发动。那个发动无效并破坏。'),
(57441100, 'Herculean Power', '金刚真力', '金剛真力', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，可以从手卡把1只4星以下的二重怪兽特殊召唤。这个效果1回合只能使用1次。'),
(52584282, 'Hercules Beetle', '海克力士甲虫', 'ヘラクレス・ビートル', 'Normal Monster', 'Insect', 'EARTH', 5, 1500, 2000, '巨大独角仙。尖角的攻击和坚硬身体的防御强而有力。'),
(300302031, 'Here Goes Something!', NULL, NULL, 'Skill Card', 'Jaden Yuki', NULL, NULL, NULL, NULL, NULL),
(4575541, 'Here There Be Dragons', '超龙灾祸', '超竜災禍', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己的手卡·墓地·除外状态的1只「征龙」怪兽特殊召唤。那之后，可以只用自己场上的「征龙」怪兽为素材进行1只「征龙」超量怪兽的超量召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己的除外状态的「征龙」怪兽任意数量为对象才能发动（相同属性最多1只）。那些怪兽回到墓地。'),
(76078185, 'Heretical Phobos Covos', '异端之弗魄祀寇猧司', '異端なるフォボスコボス', 'XYZ Monster', 'Illusion', 'DARK', 4, 2100, 1500, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：以对方场上1只效果怪兽为对象才能发动（这张卡有幻想魔族怪兽在作为超量素材的场合，这个效果在对方回合也能发动）。作为对象的怪兽的效果无效。那只怪兽是这个回合已进行战斗的场合，可以再把那个控制权直到结束阶段得到。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(51412776, 'Heritage of the Chalice', '圣杯之继承', '聖杯の継承', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的卡组·墓地选1只「圣骑士」怪兽或者1张「圣剑」卡加入手卡。 ②：这张卡在墓地存在，有「圣剑」装备魔法卡装备的自己的「圣骑士」怪兽被战斗破坏送去墓地时才能发动。这张卡加入手卡。'),
(48784854, 'Heritage of the Light', '光之继承', '光の継承', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：和已在场上存在的怪兽相同种类（仪式·融合·同调·超量）的怪兽仪式·融合·同调·超量召唤的场合才能发动。自己从卡组抽1张。'),
(90743290, 'Hermit of Prophecy', '魔导老士 艾尔米特', '魔導老士 エアミット', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1200, 700, '只要这张卡在场上表侧表示存在，每次名字带有「魔导书」的魔法卡发动，这张卡的等级上升2星，攻击力上升300。'),
(44676200, 'Hero Barrier', '英雄障壁', 'ヒーローバリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上名字中带有「元素英雄」的怪兽表侧表示存在的场合，对方怪兽的攻击只有1次无效。'),
(37412656, 'Hero Blast', '英雄炸裂', 'ヒーロー・ブラスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「元素英雄」通常怪兽为对象才能发动。那只怪兽加入手卡。那之后，选持有加入手卡的怪兽的攻击力以下的攻击力的对方场上1只怪兽破坏。'),
(19024706, 'Hero Counterattack', '英雄逆袭', 'ヒーロー逆襲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「元素英雄」的怪兽被战斗破坏时才能发动。从自己手卡对方随机选择1张卡。那张是名字带有「元素英雄」的怪兽卡的场合，对方场上1只怪兽破坏，并把选择的卡在自己场上特殊召唤。'),
(191749, 'Hero Flash!!', '英雄一闪！！', 'ヒーローフラッシュ！！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地的「H-火热之心」「E-紧急呼唤」「R-正义审判」「O-超越灵魂」从游戏中除外发动。从自己卡组特殊召唤1只名字带有「元素英雄」的通常怪兽。这个回合自己场上的名字带有「元素英雄」的通常怪兽可以直接攻击对方玩家。'),
(67951831, 'Hero Heart', '英雄之心', 'ヒーローハート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只表侧表示存在的名字带有「元素英雄」的怪兽发动。这个回合选择的怪兽的攻击力变成一半，同1次战斗阶段中可以攻击2次。'),
(32679370, 'Hero Kid', '英雄小子', 'ヒーロー・キッズ', 'Effect Monster', 'Warrior', 'EARTH', 2, 300, 600, '这张卡特殊召唤成功时，可以从卡组特殊召唤任意数量的「英雄小子」。'),
(75141056, 'Hero Mask', '英雄假面', 'ヒーロー・マスク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。从卡组把1只「元素英雄」怪兽送去墓地，作为对象的自己的表侧表示怪兽直到结束阶段当作和这个效果送去墓地的怪兽同名卡使用。'),
(10489311, 'Hero Medal', '英雄奖章', 'ヒーロー・メダル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方控制的卡的效果把盖放的这张卡破坏送去墓地时，这张卡加入卡组洗切。那之后，从自己卡组抽1张卡。'),
(30676200, 'Hero of the Ashened City', '灰灭之都的英雄', '灰滅せし都の英雄', 'Effect Monster', 'Pyro', 'DARK', 7, 2600, 2100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有「灰灭之都 奥布西地暮」存在的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方的主要阶段，以场上1只炎族怪兽为对象才能发动。那只怪兽破坏。这个效果把「灭亡龙 威多释」破坏的场合，可以再从卡组把1张「灰灭之都 奥布西地暮」在自己的场地区域表侧表示放置。'),
(89987208, 'Hero of the East', '东方英雄', '東方の英雄', 'Normal Monster', 'Warrior', 'EARTH', 3, 1100, 1000, '传说来自遥远的东方国度的武士。手持的刀相当的锋利。'),
(26647858, 'Hero Ring', '英雄光环', 'ヒーロー・ヘイロー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，攻击力1500以下的1只战士族怪兽装备。对方的攻击力1900以上的怪兽不能攻击装备怪兽。'),
(22020907, 'Hero Signal', '英雄信号', 'ヒーロー・シグナル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽被战斗破坏送去墓地时才能发动。从手卡·卡组把1只4星以下的「元素英雄」怪兽特殊召唤。'),
(81167171, 'Hero Spirit', '英雄精神', 'ヒーロースピリッツ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的名字带有「元素英雄」的怪兽被战斗破坏的场合，那个回合的战斗阶段才能发动。1只对方怪兽造成的战斗伤害为0。'),
(300302049, 'HERO World', NULL, NULL, 'Skill Card', 'Jaden Yuki', NULL, NULL, NULL, NULL, NULL),
(76442616, 'HERO''s Bond', '－英雄－之绊', 'HERO’S ボンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上有名字带有「英雄」的怪兽存在时才能发动。从手卡特殊召唤2只4星以下的名字带有「元素英雄」的怪兽。'),
(33995387, 'Hero''s Rule 1: Five Freedoms', '英雄法则1 五大自由', 'ヒーローズルール１ ファイブ・フリーダムス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己·对方的墓地的卡合计最多5张为对象才能发动。那些卡除外。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己的除外状态的1只「元素英雄」怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。'),
(85854214, 'Hero''s Rule 2', '英雄规则2', 'ヒーローズルール２', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '墓地的卡为对象的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(300302050, 'HEROES UNITE - FUSION!!', NULL, NULL, 'Skill Card', 'Jaden Yuki', NULL, NULL, NULL, NULL, NULL),
(21924381, 'Heroic Advance', '英豪前卫', 'ヒロイック・アドバンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的名字带有「英豪」的怪兽被选择作为攻击对象时，选择自己场上1只其他的4星以下的名字带有「英豪」的怪兽才能发动。选择的怪兽的攻击力直到战斗阶段结束时变成2倍，把攻击对象转移为选择的怪兽进行伤害计算。双方怪兽不会被这次战斗破坏。'),
(32175429, 'Heroic Call', '英豪呼唤', 'ヒロイック・コール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地选1只战士族怪兽特殊召唤。这个效果把「英豪」怪兽以外的怪兽特殊召唤的场合，那只怪兽不能攻击，效果无效化。 ②：自己基本分是500以下的场合，把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升自己场上的「英豪」卡以及作为超量素材中的「英豪」卡数量×500。'),
(92609670, 'Heroic Challenger - Ambush Soldier', '英豪挑战者 伏击兵', 'H・C アンブッシュ・ソルジャー', 'Effect Monster', 'Warrior', 'EARTH', 1, NULL, NULL, '自己的准备阶段时，把场上的这张卡解放才能发动。可以从自己的手卡·墓地选「英豪挑战者 伏击兵」以外的最多2只名字带有「英豪挑战者」的怪兽特殊召唤。「英豪挑战者 伏击兵」的这个效果1回合只能使用1次。这个效果特殊召唤成功时，可以通过把墓地的这张卡从游戏中除外，自己场上的全部名字带有「英豪挑战者」的怪兽的等级变成1星。'),
(65848811, 'Heroic Challenger - Assault Halberd', '英豪挑战者 强袭之戟兵', 'H・C 強襲のハルベルト', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 200, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡给与对方战斗伤害时才能发动。从卡组把1张「英豪」卡加入手卡。'),
(28194325, 'Heroic Challenger - Clasp Sword', '英豪挑战者 折刀兵', 'H・C クラスプ・ナイフ', 'Effect Monster', 'Warrior', 'EARTH', 1, 300, 100, '这个卡名的效果1回合只能使用1次。 ①：这张卡用「英豪挑战者」怪兽的效果特殊召唤成功时才能发动。从卡组把1只「英豪挑战者」怪兽加入手卡。'),
(89774530, 'Heroic Challenger - Double Lance', '英豪挑战者 双长枪兵', 'H・C ダブル・ランス', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 900, '这张卡召唤成功时，可以从自己的手卡·墓地选1只「英豪挑战者 双长枪兵」表侧守备表示特殊召唤。这张卡不能作为同调素材。此外，把这张卡作为超量素材的场合，不是战士族怪兽的超量召唤不能使用。'),
(34143852, 'Heroic Challenger - Extra Sword', '英豪挑战者 额外之剑', 'H・C エクストラ・ソード', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1000, '这张卡为素材的超量怪兽得到以下效果。 ●这次超量召唤成功时，这张卡的攻击力上升1000。'),
(71549257, 'Heroic Challenger - Knuckle Sword', '英豪挑战者 拳套刀兵', 'H・C ナックル・ナイフ', 'Effect Monster', 'Warrior', 'EARTH', 1, 600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有1星怪兽以外的「英豪」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以自己场上1只战士族怪兽为对象才能发动。那只怪兽和这张卡的等级变成和那之内的1只的等级相同。这个效果的发动后，直到回合结束时自己不用超量怪兽不能攻击宣言。'),
(18548966, 'Heroic Challenger - Morning Star', '英豪挑战者 晨星锤兵', 'H・C モーニング・スター', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1300, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有战士族怪兽2只以上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「英豪」魔法·陷阱卡加入手卡。 ③：这张卡在墓地存在，自己基本分是500以下的场合才能发动。这张卡效果无效特殊召唤。'),
(61132951, 'Heroic Challenger - Night Watchman', '英豪挑战者 夜袭之提灯兵', 'H・C 夜襲のカンテラ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 300, '这张卡向对方场上守备表示存在的怪兽攻击的场合，伤害计算前可以把那只怪兽破坏。'),
(50491121, 'Heroic Challenger - Spartan', '英豪挑战者 斯巴达兵', 'H・C スパルタス', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1000, '1回合1次，对方怪兽的攻击宣言时选择这张卡以外的自己场上1只名字带有「英豪」的怪兽才能发动。这张卡的攻击力直到战斗阶段结束时上升选择的怪兽的原本攻击力数值。'),
(52370835, 'Heroic Challenger - Swordshield', '英豪挑战者 剑盾兵', 'H・C ソード・シールド', 'Effect Monster', 'Warrior', 'EARTH', 4, NULL, 2000, '自己场上有名字带有「英豪」的怪兽存在的场合，把这张卡从手卡送去墓地才能发动。这个回合，战斗发生的对自己的战斗伤害变成0，自己场上的名字带有「英豪」的怪兽不会被战斗破坏。这个效果在对方回合也能发动。'),
(1833916, 'Heroic Challenger - Thousand Blades', '英豪挑战者 千刃', 'H・C サウザンド・ブレード', 'Effect Monster', 'Warrior', 'EARTH', 4, 1300, 1100, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，从手卡丢弃1张「英豪」卡才能发动。从卡组把1只「英豪」怪兽特殊召唤，这张卡变成守备表示。这个效果的发动后，直到回合结束时自己不是「英豪」怪兽不能特殊召唤。 ②：这张卡在墓地存在，战斗·效果让自己受到伤害时才能发动。这张卡攻击表示特殊召唤。'),
(26885836, 'Heroic Challenger - War Hammer', '英豪挑战者 战锤兵', 'H・C ウォー・ハンマー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2100, 1300, '这张卡战斗破坏对方怪兽送去墓地时，可以把破坏的怪兽当作装备卡使用只有1只给这张卡装备。这张卡的攻击力上升这个效果装备的怪兽的攻击力数值。'),
(97453744, 'Heroic Champion - Claivesolish', '英豪冠军 辉剑王', 'H－C クレイヴソリッシュ', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2000, '战士族4星怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：对方不能选择其他怪兽作为攻击对象。 ②：把基本分支付到变成500基本分才能发动。这个回合的战斗阶段开始时，选自己场上1只怪兽把攻击力变成2倍。 ③：对方怪兽进行战斗的攻击宣言时，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。这张卡的攻击力直到回合结束时上升那只怪兽的攻击力数值。'),
(60645181, 'Heroic Champion - Excalibur', '英豪胜利者 王者之剑', 'H－C エクスカリバー', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 2000, '战士族4星怪兽×2 ①：1回合1次，把这张卡2个超量素材取除才能发动。这张卡的攻击力直到对方回合结束时变成原本攻击力的2倍。'),
(48009503, 'Heroic Champion - Gandiva', '英豪冠军 英弓王', 'H－C ガーンデーヴァ', 'XYZ Monster', 'Warrior', 'EARTH', 4, 2100, 1800, '战士族4星怪兽×2 对方场上有4星以下的怪兽特殊召唤时，可以通过把这张卡1个超量素材取除，那些特殊召唤的怪兽破坏。这个效果1回合只能使用1次。'),
(23848752, 'Heroic Champion - Jarngreipr', '英豪冠军 铁手套王', 'H－C ヤールングレイプ', 'XYZ Monster', 'Warrior', 'EARTH', 1, 700, 1800, '战士族1星怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的战士族怪兽在1回合各有1次不会被战斗·效果破坏。 ②：把这张卡2个超量素材取除，以自己墓地1只等级或者阶级是4的战士族怪兽为对象才能发动。那只怪兽特殊召唤，这张卡的攻击力上升那个原本攻击力数值。 ③：对方怪兽进行战斗的攻击宣言时才能发动。自己基本分回复那只怪兽的攻击力一半的数值。'),
(74593218, 'Heroic Champion - Kusanagi', '英豪冠军 草薙剑王', 'H－C クサナギ', 'XYZ Monster', 'Warrior', 'EARTH', 4, 2500, 2400, '战士族4星怪兽×3 1回合1次，把这张卡1个超量素材取除才能发动。陷阱卡的发动无效并破坏。那之后，这张卡的攻击力上升500。'),
(14301396, 'Heroic Champion - Magnum Excalibur', '英豪胜利者 最强王者之剑', 'H－C マグナム・エクスカリバー', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 2000, '战士族4星怪兽×2 ①：这张卡和对方怪兽进行战斗的伤害计算时，把这张卡2个超量素材取除才能发动。这张卡的攻击力只在那次伤害计算时变成2倍。 ②：1回合1次，自己·对方的主要阶段，以自己场上1只其他的表侧表示怪兽为对象才能发动。自己场上的这张卡当作攻击力·守备力上升2000的装备魔法卡使用给作为对象的怪兽装备。 ③：把墓地的这张卡除外才能发动。从自己墓地让3只战士族怪兽回到卡组。'),
(53466826, 'Heroic Chance', '英豪机会', 'ヒロイック・チャンス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「英豪」的怪兽才能发动。这个回合，选择的怪兽攻击力变成2倍，不能向对方玩家直接攻击。「英豪机会」在1回合只能发动1张。'),
(45337544, 'Heroic Envoy', '英豪使者', 'ヒロイック・エンヴォイ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「英豪」怪兽加入手卡。 ②：自己基本分是500以下的场合，把墓地的这张卡除外，以自己墓地1张「英豪」卡为对象才能发动。那张卡加入手卡。'),
(95920682, 'Heroic Gift', '英豪礼物', 'ヒロイック・ギフト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方基本分是2000以下的场合才能发动。把对方基本分变成8000并从自己卡组抽2张卡。「英豪礼物」在1回合只能发动1张。'),
(49551909, 'Heroic Retribution Sword', '英豪复仇剑', 'ヒロイック・リベンジ・ソード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上1只名字带有「英豪」的怪兽装备。装备怪兽的战斗发生的对自己的战斗伤害让对方也承受。此外，和装备怪兽进行战斗的对方怪兽在伤害计算后破坏。'),
(70703416, 'Hexa Spirit of the Ice Barrier', '冰结界的霜精', '氷結界の霜精', 'Tuner Monster', 'Sea Serpent', 'WATER', 1, 400, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有其他的「冰结界」怪兽存在，对方场上的怪兽的攻击力·守备力下降500。 ②：自己主要阶段才能发动。从卡组把1只3星以下的「冰结界」怪兽送去墓地。这张卡的等级直到回合结束时变成和那只怪兽相同。'),
(70422863, 'Hexatellarknight', '守星骑士六角结界', '星守る結界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「星骑士」超量怪兽的攻击力·守备力上升那超量素材数量×200。 ②：自己场上的「星骑士」超量怪兽被选择作为攻击对象时，把手卡1张「星骑士」卡送去墓地才能发动。那次攻击无效。'),
(46294982, 'Hexe Trude', '女巫特露德', 'ヘクサ・トルーデ', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2600, 2100, '①：场地区域有「急流山的金宫」存在的场合，这张卡可以不用解放作召唤。 ②：1回合1次，场地区域有「急流山的金宫」存在的场合，以场上1张卡为对象才能发动。那张卡破坏，这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡战斗破坏对方怪兽时，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升400。'),
(64697431, 'Hey, Trunade!', '局部性飓风', '局所的ハリケーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上盖放的魔法·陷阱卡全部回到持有者手卡。'),
(91677585, 'Hi-Five the Sky', '勇往翔前的挑战', 'かっとビング・チャレンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己战斗阶段，以这个回合进行过攻击的1只超量怪兽为对象才能发动。这次战斗阶段中，那只怪兽只再1次可以攻击。这个效果让那只怪兽攻击的场合，直到伤害步骤结束时对方不能把魔法·陷阱·怪兽的效果发动。'),
(15555120, 'Hi-Speed Re-Level', '高速疾行等级再现', 'ハイ・スピード・リレベル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己墓地1只「疾行机人」怪兽除外，以自己场上1只同调怪兽为对象才能发动。那只怪兽直到回合结束时变成和除外的怪兽相同等级，攻击力上升除外的怪兽的等级×500。'),
(42110604, 'Hi-Speedroid Chanbara', '高速疾行机人 剑剧骑手', 'HSRチャンバライダー', 'Synchro Monster', 'Machine', 'WIND', 5, 2000, 1000, '调整＋调整以外的怪兽1只以上 自己对「高速疾行机人 比剑骑手」1回合只能有1次特殊召唤。 ①：这张卡在同1次的战斗阶段中可以作2次攻击。 ②：这张卡进行战斗的伤害步骤开始时发动。这张卡的攻击力上升200。 ③：这张卡被送去墓地的场合，以除外的1张自己的「疾行机人」卡为对象才能发动。那张卡加入手卡。'),
(86154370, 'Hi-Speedroid Clear Wing Rider', '高速疾行机人 遥控清透翼骑手', 'HSR／CWライダー', 'Synchro Monster', 'Machine', 'WIND', 11, 3500, 2000, '风属性调整＋调整以外的风属性同调怪兽1只 ①：1回合1次，自己主要阶段才能发动。掷1次骰子。选最多有出现的数目数量的自己墓地的风属性怪兽回到卡组。那之后，可以选最多有回去数量的对方场上的卡破坏。这张卡的攻击力直到回合结束时上升这个效果破坏的数量×500。 ②：对方主要阶段，把同调召唤的这张卡解放才能发动。从额外卡组把最多2只7星风属性同调怪兽特殊召唤（同名卡最多1张）。'),
(23361526, 'Hi-Speedroid Cork Shooter', '高速疾行机人 软木塞枪', 'HSRコルク－１０', 'Synchro Tuner Monster', 'Machine', 'WIND', 3, 500, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的效果1回合只能使用1次，这个效果发动的回合，自己不是风属性怪兽不能特殊召唤。 ①：这张卡同调召唤成功的场合，可以从以下效果选择1个发动。 ●从卡组把1张「疾行机人」魔法·陷阱卡加入手卡。 ●这张卡只用「疾行机人」怪兽为素材作同调召唤的场合，若那次同调召唤使用过的一组同调素材怪兽全部在自己墓地齐集，那一组特殊召唤。'),
(10732060, 'Hi-Speedroid Glider #2', '高速疾行机人 滑翔飞镖', 'HSRグライダー２', 'Synchro Tuner Monster', 'Machine', 'WIND', 5, 1600, 2200, '机械族·风属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以除调整外的自己墓地1只7星以下的风属性同调怪兽为对象才能发动。那只怪兽特殊召唤。 ②：对方把怪兽特殊召唤的场合，若自己场上有「幻透翼」怪兽存在，把墓地的这张卡除外才能发动。对方场上的全部怪兽的等级上升5星。'),
(21516908, 'Hi-Speedroid Hagoita', '高速疾行机人 马赫羽子板', 'HSRマッハゴー・イータ', 'Synchro Monster', 'Machine', 'WIND', 5, 2000, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：把这张卡解放才能发动。场上的全部表侧表示怪兽的等级直到回合结束时上升1星。这个效果在对方回合也能发动。 ②：这张卡在墓地存在，自己场上有「疾行机人」调整存在的场合才能发动。这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(97007933, 'Hi-Speedroid Kendama', '高速疾行机人 魔剑玉', 'HSR魔剣ダーマ', 'Synchro Monster', 'Machine', 'WIND', 6, 2200, 1600, '调整＋调整以外的怪兽1只以上 「高速疾行机人 魔剑玉」的②③的效果1回合各能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：把自己墓地1只机械族怪兽除外才能发动。给与对方500伤害。 ③：这张卡在墓地存在，自己场上没有卡存在的场合，自己主要阶段才能发动。这张卡从墓地特殊召唤。这个效果发动的回合，自己不能通常召唤。'),
(5772618, 'Hi-Speedroid Kitedrake', '高速疾行机人 风筝德雷克龙', 'HSRカイドレイク', 'Synchro Monster', 'Machine', 'WIND', 8, 3000, 2800, '机械族·风属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合，可以从以下效果选择1个发动。 ●这张卡以外的场上的卡全部破坏。 ●对方场上的全部表侧表示的卡的效果无效。 ②：这张卡被对方送去墓地的场合才能发动。从卡组把1只「疾行机人」怪兽加入手卡。'),
(86943389, 'Hi-Speedroid Puzzle', '高速疾行机人 快刀乱破拼图', 'HSR快刀乱破ズール', 'Synchro Monster', 'Machine', 'WIND', 4, 1300, 1600, '调整＋调整以外的怪兽1只以上 ①：这张卡和特殊召唤的怪兽进行战斗的伤害步骤开始时才能发动。这张卡的攻击力直到那次伤害步骤结束时变成2倍。 ②：同调召唤的这张卡被送去墓地的回合的结束阶段，以「高速疾行机人 快刀乱破智游」以外的自己墓地1只「疾行机人」怪兽为对象才能发动。那只怪兽加入手卡。'),
(72813401, 'Hi-Speedroid Rubber Band Shooter', '高速疾行机人 皮筋机枪', 'HSR－GOMガン', 'Link Monster', 'Machine', 'WIND', NULL, 1000, NULL, '风属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。进行1只风属性怪兽的召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：从额外卡组把1只风属性同调怪兽除外才能发动。等级合计直到变成和除外的怪兽相同为止，从卡组把2只卡名不同的「疾行机人」怪兽给对方观看，对方从那之中随机选1只。那1只怪兽加入自己手卡，剩余送去墓地。'),
(69109764, 'Hibernation Dragon', '休眠龙', 'ハイバネーション・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 3, 600, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己墓地1只4星以下的龙族怪兽为对象才能发动。那只怪兽加入手卡。 ②：自己场上没有连接怪兽存在的场合，把墓地的这张卡除外，以自己墓地1只龙族·暗属性的连接怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(64501875, 'Hibikime', '响女', '響女', 'Normal Monster', 'Warrior', 'EARTH', 4, 1450, 1000, '发出扰乱听觉的噪音，使对方陷入行动不能的状态。'),
(52105192, 'Hidden Armory', '武器秘洞', 'アームズ・ホール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能通常召唤。 ①：把卡组最上面的卡送去墓地才能发动。从自己的卡组·墓地选1张装备魔法卡加入手卡。'),
(47128571, 'Hidden Fangs of Revenge', '报复的隐齿', '報復の隠し歯', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。 ①：自己或者对方的怪兽的攻击宣言时才能发动。选自己场上盖放的2张卡破坏，那次攻击无效。并且，这个效果破坏送去墓地的卡之中有怪兽卡的场合，再选那之内的1只。持有选的怪兽的守备力以下的攻击力的对方场上的怪兽全部破坏，那之后变成这个回合的结束阶段。'),
(300203004, 'Hidden Parasite', NULL, NULL, 'Skill Card', 'Weevil', NULL, NULL, NULL, NULL, NULL),
(2047519, 'Hidden Soldiers', '伏兵', '隠れ兵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把怪兽召唤·反转召唤时才能发动。从手卡把1只4星以下的暗属性怪兽特殊召唤。'),
(21840375, 'Hidden Spellbook', '隐藏的魔导书', '隠された魔導書', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡在自己回合才能发动。选择自己墓地存在的2张魔法卡，加入卡组洗切。'),
(94317736, 'Hidden Springs of the Far East', '极东秘泉乡', '極東秘泉郷', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方玩家1回合1次，自己主要阶段2才能发动。自己回复500基本分，这个回合中，以下效果适用。 ●自己怪兽的召唤·特殊召唤不会被无效化。 ●包含把怪兽特殊召唤效果的怪兽的效果·魔法·陷阱卡由自己发动的场合，那个发动不会被无效化。 ●自己场上盖放的魔法·陷阱卡不会成为对方的效果的对象，不会被对方的效果破坏。'),
(70000776, 'Hidden Temples of Necrovalley', '王家长眠之谷的祭殿', 'ネクロバレーの祭殿', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上有名字带有「守墓」的怪兽以及「王家长眠之谷」存在的场合才能发动。只要这张卡在场上存在，双方不能把名字带有「守墓」的怪兽以外的怪兽特殊召唤。名字带有「守墓」的怪兽以及「王家长眠之谷」不在场上存在的场合，这张卡破坏。'),
(26232916, 'Hidden Village of Ninjitsu Arts', '隐之里-忍法修炼之地', '隠れ里－忍法修練の地', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「忍者」怪兽召唤·反转召唤·特殊召唤的场合，以自己墓地1只「忍者」怪兽或者1张「忍法」卡为对象才能发动。那张卡加入手卡。这个回合，自己不能作这个效果加入手卡的卡以及那些同名卡的效果的发动。 ②：自己场上的「忍者」怪兽或者「忍法」卡被战斗或者对方的效果破坏的场合，可以作为代替把自己墓地1只「忍者」怪兽除外。'),
(82260502, 'Hieracosphinx', '斯芬克斯 海尔拉克', 'ヒエラコスフィンクス', 'Effect Monster', 'Rock', 'EARTH', 6, 2400, 1200, '只要这张卡在自己场上表侧表示存在，对方不能选择里侧守备表示的怪兽作为攻击对象。'),
(300302009, 'Hieratic Chant', NULL, NULL, 'Skill Card', 'Yami Marik', NULL, NULL, NULL, NULL, NULL),
(27337596, 'Hieratic Dragon King of Atum', '圣刻龙王－亚图姆斯', '聖刻龍王－アトゥムス', 'XYZ Monster', 'Dragon', 'LIGHT', 6, 2400, 2100, '龙族6星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从卡组选1只龙族怪兽，攻击力·守备力变成0特殊召唤。这个效果发动的回合，这张卡不能攻击。'),
(30794966, 'Hieratic Dragon of Asar', '圣刻龙－乌西尔龙', '聖刻龍－ウシルドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2600, 700, '这张卡可以把自己墓地的龙族·光属性怪兽和龙族的通常怪兽各1只从游戏中除外，从手卡特殊召唤。场上的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「圣刻」的怪兽解放。'),
(4022819, 'Hieratic Dragon of Eset', '圣刻龙－阿赛特龙', '聖刻龍－アセトドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 5, 1900, 1200, '这张卡可以不用解放作召唤。这个方法召唤的这张卡的原本攻击力变成1000。1回合1次，选择场上1只龙族的通常怪兽才能发动。场上的全部名字带有「圣刻」的怪兽的等级直到结束阶段时变成和选择的怪兽相同等级。此外，这张卡被解放时，从自己的手卡·卡组·墓地选1只龙族的通常怪兽，攻击力·守备力变成0特殊召唤。'),
(78033100, 'Hieratic Dragon of Gebeb', '圣刻龙－龙人盖布', '聖刻龍－ドラゴンゲイヴ', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1800, 400, '这张卡战斗破坏对方怪兽送去墓地时，从自己的手卡·卡组·墓地选1只龙族的通常怪兽，攻击力·守备力变成0特殊召唤。此外，这张卡被解放时，从自己的手卡·卡组·墓地把1只名字带有「圣刻」的通常怪兽特殊召唤。'),
(31516413, 'Hieratic Dragon of Nebthet', '圣刻龙－奈芙蒂龙', '聖刻龍－ネフテドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 5, 2000, 1600, '这张卡可以把自己场上1只名字带有「圣刻」的怪兽解放从手卡特殊召唤。1回合1次，可以把这张卡以外的自己的手卡·场上1只名字带有「圣刻」的怪兽解放，选择对方场上1只怪兽破坏。此外，这张卡被解放时，从自己的手卡·卡组·墓地选1只龙族的通常怪兽，攻击力·守备力变成0特殊召唤。'),
(41639001, 'Hieratic Dragon of Nuit', '圣刻龙－龙人努特', '聖刻龍－ドラゴンヌート', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1700, 900, '场上表侧表示存在的这张卡成为魔法·陷阱·效果怪兽的效果的对象时发动。从自己的手卡·卡组·墓地选1只龙族的通常怪兽，攻击力·守备力变成0特殊召唤。这个效果1回合只能使用1次。'),
(3300267, 'Hieratic Dragon of Su', '圣刻龙－舒龙', '聖刻龍－シユウドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2200, 1000, '①：这张卡可以把自己场上1只「圣刻」怪兽解放从手卡特殊召唤。 ②：1回合1次，把这张卡以外的自己的手卡·场上1只「圣刻」怪兽解放，以对方场上1张魔法·陷阱卡为对象才能发动。那张对方的卡破坏。 ③：这张卡被解放的场合发动。从自己的手卡·卡组·墓地选1只龙族通常怪兽，攻击力·守备力变成0特殊召唤。'),
(66789970, 'Hieratic Dragon of Sutekh', '圣刻龙－赛特克龙', '聖刻龍－セテクドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 2000, '这张卡不能通常召唤。把自己墓地3只龙族的通常怪兽从游戏中除外的场合可以特殊召唤。1回合1次，可以把自己墓地1只龙族怪兽从游戏中除外，选择场上1张卡破坏。'),
(77901552, 'Hieratic Dragon of Tefnuit', '圣刻龙－泰芙努龙', '聖刻龍－トフェニドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2100, 1400, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的回合，这张卡不能攻击。 ②：这张卡被解放的场合发动。从自己的手卡·卡组·墓地选1只龙族通常怪兽，攻击力·守备力变成0特殊召唤。'),
(53670497, 'Hieratic Seal From the Ashes', '复活之圣刻印', '復活の聖刻印', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方回合1次，可以从卡组把1只名字带有「圣刻」的怪兽送去墓地。此外，自己回合1次，可以选择从游戏中除外的1只自己的名字带有「圣刻」的怪兽回到墓地。场上表侧表示存在的这张卡被送去墓地时，选择自己墓地1只名字带有「圣刻」的怪兽特殊召唤。'),
(11975962, 'Hieratic Seal of Banishment', '抹杀之圣刻印', '抹殺の聖刻印', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「圣刻」的怪兽解放才能发动。选择对方场上1张卡从游戏中除外。'),
(25377819, 'Hieratic Seal of Convocation', '召集之圣刻印', '召集の聖刻印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「圣刻」怪兽加入手卡。'),
(39680372, 'Hieratic Seal of Creation', '创造之圣刻印', '創造の聖刻印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只龙族超量怪兽为对象才能发动。原本卡名和那只自己怪兽不同的1只「圣刻」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「圣刻」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(47360060, 'Hieratic Seal of Reflection', '反射之圣刻印', '反射の聖刻印', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「圣刻」的怪兽解放才能发动。效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(51365514, 'Hieratic Seal of Supremacy', '超力之圣刻印', '超力の聖刻印', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「圣刻」的怪兽特殊召唤。'),
(64514622, 'Hieratic Seal of the Dragon King', '龙王之圣刻印', '龍王の聖刻印', 'Gemini Monster', 'Dragon', 'LIGHT', 6, NULL, NULL, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。可以通过把场上表侧表示存在的这张卡当作通常召唤作再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●把这张卡解放才能发动。从自己的手卡·卡组·墓地选「龙王之圣刻印」以外的1只名字带有「圣刻」的怪兽表侧守备表示特殊召唤。'),
(24361622, 'Hieratic Seal of the Heavenly Spheres', '天球之圣刻印', '天球の聖刻印', 'Link Monster', 'Dragon', 'LIGHT', NULL, NULL, NULL, '龙族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：对方回合1次，这张卡在额外怪兽区域存在的场合，把自己的手卡·场上1只怪兽解放才能发动。场上1张表侧表示卡回到手卡。 ②：这张卡被解放的场合发动。从手卡·卡组把1只龙族怪兽攻击力·守备力变成0特殊召唤。'),
(13140300, 'Hieratic Seal of the Sun Dragon Overlord', '神龙之圣刻印', '神龍の聖刻印', 'Normal Monster', 'Dragon', 'LIGHT', 8, NULL, NULL, '被刻有神秘刻印的神圣古物。传说是将施展如神一般的力量之龙的力量封印之物。在黄金太阳之下，经历悠久的时光，后来随着其神圣性被称为太阳石。'),
(3292267, 'Hieratic Sky Dragon Overlord of Heliopolis', '圣刻天龙－九柱神', '聖刻天龍－エネアード', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2400, '8星怪兽×2 ①：1回合1次，以自己的场上·墓地的卡或者除外的自己的卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(64332231, 'Hieratic Sun Dragon Overlord of Heliopolis', '圣刻神龙－九柱神', '聖刻神龍－エネアード', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2400, '8星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己的手卡·场上的怪兽任意数量解放，选那个数量的场上的卡破坏。'),
(10248192, 'Hieroglyph Lithograph', '圣书体石板', 'ヒエログリフの石版', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分。在本次决斗中，自己的手卡制限张数为7张。'),
(92918648, 'Hierophant of Prophecy', '魔导法皇 海隆', '魔導法皇 ハイロン', 'XYZ Monster', 'Spellcaster', 'DARK', 7, 2800, 2600, '魔法师族7星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。选最多有自己墓地的名字带有「魔导书」的魔法卡数量的对方场上的魔法·陷阱卡破坏。'),
(86585274, 'High Priestess of Prophecy', '魔导法士 朱诺', '魔導法士 ジュノン', 'Effect Monster', 'Spellcaster', 'LIGHT', 7, 2500, 2100, '①：把手卡3张「魔导书」魔法卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，从自己的手卡·墓地把1张「魔导书」魔法卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(70569684, 'High Rate Draw', '高速率抽卡', 'ハイレート・ドロー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：选自己场上的怪兽2只以上任意数量破坏，破坏的怪兽每有2只，自己从卡组抽1张。 ②：这张卡在墓地存在的场合，对方主要阶段，以自己场上1只怪兽为对象才能发动。那只怪兽破坏，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(36350300, 'High Ritual Art', '高尚仪式术', '高尚儀式術', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '仪式怪兽的降临必需。这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把手卡的通常怪兽解放，从卡组把1只仪式怪兽仪式召唤。这个效果特殊召唤的怪兽在对方结束阶段回到持有者卡组。'),
(54579801, 'High Tide Gyojin', '满潮鱼人', '満ち潮のマーマン', 'Normal Monster', 'Aqua', 'WATER', 4, 1650, 1300, '能在水中自由游动的半人鱼战士，攻击力强劲。'),
(32542011, 'High Tide on Fire Island', '燃起的大海', '燃え上がる大海', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有7星以上的水属性或者炎属性的怪兽存在的场合才能发动。自己场上的怪兽属性的以下效果适用。 ●水属性：把这个回合为让效果怪兽的效果发动而被送去自己墓地的水属性怪兽尽可能特殊召唤。那之后，选自己场上1只怪兽破坏。 ●炎属性：选场上1只怪兽破坏。那之后，自己手卡有1张以上的场合，选1张丢弃去墓地。'),
(11248645, 'Highness Archfiend', '殿下恶魔', 'ハイネス・デーモン', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1000, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤的场合，从自己墓地把1张「恶魔」卡除外才能发动。从卡组把「殿下恶魔」以外的2张「恶魔」卡加入手卡。这个效果的发动后，直到回合结束时自己不是「恶魔」怪兽不能从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己的仪式怪兽被战斗破坏时才能发动。这张卡特殊召唤。'),
(76615300, 'Hiita the Fire Channeler', '火灵媒师 希塔', '火霊媒師ヒータ', 'Effect Monster', 'Spellcaster', 'FIRE', 5, 1850, 1500, '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只炎属性怪兽丢弃才能发动。比这张卡以外的丢弃的怪兽攻击力高的1只炎属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把炎属性以外的怪兽的效果发动。 ②：自己的炎属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。'),
(759393, 'Hiita the Fire Charmer', '火灵使 希塔', '火霊使いヒータ', 'Flip Effect Monster', 'Spellcaster', 'FIRE', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只炎属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到作为对象的怪兽的控制权。'),
(48815792, 'Hiita the Fire Charmer, Ablaze', '灼热之火灵使 希塔', '灼熱の火霊使いヒータ', 'Link Monster', 'Spellcaster', 'FIRE', NULL, 1850, NULL, '包含炎属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只炎属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的炎属性怪兽加入手卡。'),
(71459017, 'Hinezumi Hanabi', '祢须三破鸣比', '禰須三破鳴比', 'Effect Monster', 'Beast', 'FIRE', 4, 2000, 200, '这张卡不能作为融合·同调·超量·连接召唤的素材。 ①：这张卡召唤·特殊召唤成功的场合发动。给这张卡放置6个指示物。 ②：自己结束阶段发动。这张卡的控制权移给对方。 ③：1回合1次，有指示物放置的这张卡的控制权转移的场合发动。掷1次骰子，这张卡的指示物把最多有出现数目的数量尽可能取除。这个效果让这张卡的指示物全部被取除的场合，这张卡破坏，自己受到2000伤害。'),
(75745607, 'Hino-Kagu-Tsuchi', '火之迦具土', '火之迦具土', 'Spirit Monster', 'Pyro', 'FIRE', 8, 2800, 2900, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。此外，这张卡给与对方玩家战斗伤害时发动。下个回合的抽卡阶段的抽卡前对方把全部手卡丢弃。'),
(46130346, 'Hinotama', '火球', 'ファイヤー・ボール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方500伤害。'),
(96851799, 'Hinotama Soul', '刺焰球', 'スティング', 'Normal Monster', 'Pyro', 'FIRE', 2, 600, 500, '非常炽热的火焰形成的块，并用那身体冲撞敌人。'),
(7778726, 'Hip Hoshiningen', '高级星', 'ハイパースター', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1400, NULL, '光属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的光属性怪兽的攻击力·守备力上升500，暗属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只光属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(18027138, 'Hippo Carnival', '河马狂欢节', 'カバーカーニバル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：在自己场上把3只「河马衍生物」（兽族·地·1星·攻/守0）特殊召唤。这衍生物不能解放。只要「河马衍生物」在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。这张卡的发动后，直到回合结束时对方不能把「河马衍生物」以外的怪兽作为攻击对象。'),
(11050416, 'Hippo Token', '超河马嘉年华', '超カバーカーニバル', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(81863068, 'Hiro''s Shadow Scout', '恶魔侦察者', '悪魔の偵察者', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 650, 500, '反转：对方从卡组抽3张卡。这个效果抽到的卡给双方确认，从那之中把魔法卡全部丢弃去墓地。'),
(46718686, 'Hitodenchak', '海星葵', 'ヒトデンチャク', 'Normal Monster', 'Aqua', 'WATER', 2, 600, 700, '被污染的水源侵蚀而狂暴化的海星。从口中吐出溶解液攻击敌人。'),
(76184692, 'Hitotsu-Me Giant', '独眼巨人', 'サイクロプス', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1200, 1000, '一只眼的巨人。会用粗壮的双臂攻过来。必须注意。'),
(41306080, 'Hiyari @Ignister', '凉飕飕＠伊格尼斯者', 'ヒヤリ＠イグニスター', 'Effect Monster', 'Cyberse', 'WATER', 1, 300, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「@火灵天星」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把这张卡以外的自己场上1只电子界族怪兽解放才能发动。从卡组把1只5星以上的「@火灵天星」怪兽加入手卡，这张卡的等级直到回合结束时变成4星。为这个效果发动而把连接怪兽解放的场合，可以再从卡组把1张「“艾”之仪式」加入手卡。'),
(88919365, 'Hojo the Vaylantz Warrior', '弈勇之武者－北条', 'ヴァリアンツの武者－北条', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 8, 1900, 1900, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：以魔法与陷阱区域1张表侧表示的卡为对象才能发动。那张卡回到持有者手卡。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合才能发动。从自己的手卡·场上把「群豪」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，自己的灵摆区域存在的融合素材怪兽也能作为融合素材使用。'),
(10000040, 'Holactie the Creator of Light', '光之创造神 哈拉克提', '光の創造神 ホルアクティ', 'Effect Monster', 'Creator God', 'DIVINE', 12, -1, -1, '这张卡不能通常召唤。把自己场上的原本卡名是「奥西里斯之天空龙」「欧贝利斯克之巨神兵」「太阳神之翼神龙」的怪兽各1只解放的场合才能特殊召唤。这张卡的特殊召唤不会被无效化。把这张卡特殊召唤的玩家决斗胜利。'),
(43730887, 'Holding Arms', '拘束臂', 'ホールディング・アームズ', 'Effect Monster', 'Fiend', 'DARK', 4, 500, 1200, '①：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象发动。这只怪兽表侧表示存在期间，作为对象的表侧表示怪兽不能攻击，效果无效化。 ②：只要这张卡的①的效果作为对象的怪兽在场上存在，这张卡不会被战斗·效果破坏。'),
(70124586, 'Holding Legs', '拘束足', 'ホールディング・レッグス', 'Effect Monster', 'Fiend', 'DARK', 4, 800, 600, '①：这张卡召唤·反转召唤·特殊召唤成功的场合发动。场上盖放的魔法·陷阱卡全部回到持有者手卡。 ②：把墓地的这张卡除外，以对方场上盖放的1张魔法·陷阱卡为对象才能发动。直到下个回合的结束时那张卡不能发动。'),
(15462014, 'Hollow Giants', '龙马踬图', '龍馬躓図', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '从额外卡组特殊召唤的怪兽在双方场上存在的场合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，从额外卡组特殊召唤的表侧表示怪兽的效果无效化。 ②：从额外卡组特殊召唤的怪兽之间的战斗让怪兽被破坏的场合发动。这张卡送去墓地，那次战斗破坏的怪兽的控制者受到1000伤害。'),
(51548207, 'Hollowrokket Dragon', '空尖枪弹龙', 'ホロウヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 2400, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，从对方卡组上面把最多6张卡翻开，从那之中选1张除外，剩余用原本的顺序回到卡组上面。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「空尖弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(10859908, 'Holograh', '全息投影者', 'ホログラー', 'Normal Monster', 'Machine', 'EARTH', 3, 1100, 700, '使人看见各种幻想、趁机进行攻击的机器。'),
(40410110, 'Homunculus the Alchemic Being', '炼金生物 人工生命体', '錬金生物 ホムンクルス', 'Effect Monster', 'Plant', 'LIGHT', 4, 1800, 1600, '这只怪兽的属性可以改变。这个效果1回合可以使用1次。'),
(37742478, 'Honest', '奥尼斯特', 'オネスト', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1100, 1900, '①：自己主要阶段才能发动。场上的表侧表示的这张卡回到手卡。 ②：自己的光属性怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只怪兽的攻击力直到回合结束时上升进行战斗的对方怪兽的攻击力数值。'),
(34472920, 'Honeybot', '蜜罐机器人', 'ハニーボット', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1900, NULL, '电子界族怪兽2只 ①：这张卡所连接区的怪兽不会成为效果的对象，不会被战斗破坏。'),
(1980574, 'Hop Ear Squadron', '跃耳兔飞行队', 'ホップ・イヤー飛行隊', 'Tuner Monster', 'Beast', 'WIND', 2, 300, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，对方主要阶段，以自己场上1只表侧表示怪兽为对象才能发动。这张卡特殊召唤。那之后，只用这张卡和作为对象的怪兽为素材进行同调召唤。'),
(80036543, 'Hope for Escape', '通往活路的希望', '活路への希望', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己基本分比对方少1000以上的场合，支付1000基本分才能发动。双方基本分差每有2000，自己从卡组抽1张。'),
(69669405, 'Horn Imp', '小鬼', 'インプ', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 1000, '住在黑暗的小鬼。攻击意外的强。要注意它头上的角。'),
(98069388, 'Horn of Heaven', '升天之角笛', '昇天の角笛', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上的1只怪兽作为祭品。怪兽的召唤·反转召唤·特殊召唤无效并破坏。');